def trigger_emotional_intervention(
    user_id,
    real_time_metrics,
    historical_data,
    consent_settings=None,
    current_context=None
):
    """
    Decide whether to offer a supportive learning intervention.

    Inputs:
      user_id: pseudonymous student identifier
      real_time_metrics: {
          "typing_speed": float | None,
          "voice_pitch": float | None,
          "sentiment_score": float | None,  # range: -1.0 to 1.0
          "confidence": float | None
      }
      historical_data: {
          "recent_error_rate": float | None,
          "recent_session_duration": int | None,
          "prior_preferences": dict,
          "prior_support_responses": list,
          "last_intervention_time": datetime | None
      }
      consent_settings: user-controlled permissions
      current_context: lesson/task metadata

    Returns:
      A support action, or {"action": "none"}
    """

    # ---------- 1. Privacy and consent checks ----------
    if not consent_settings or not consent_settings.get("proactive_support", False):
        return {"action": "none", "reason": "proactive_support_not_enabled"}

    if not consent_settings.get("emotion_signal_processing", False):
        return {"action": "none", "reason": "emotion_signal_processing_not_enabled"}

    # Do not retain raw voice, keystrokes, or inferred emotional labels.
    metrics = aggregate_and_minimize(real_time_metrics)

    # ---------- 2. Validate signal quality ----------
    # Voice pitch, typing speed, and sentiment are noisy and culturally/contextually
    # variable. Never act on a single weak signal.
    if metrics["confidence"] is None or metrics["confidence"] < 0.70:
        return {"action": "none", "reason": "low_signal_confidence"}

    if not sufficient_recent_observations(metrics):
        return {"action": "none", "reason": "insufficient_evidence"}

    # ---------- 3. Detect learning friction, not a presumed emotion ----------
    friction_score = estimate_learning_friction(
        metrics=metrics,
        history=historical_data,
        context=current_context
    )

    # Example: combine recent errors, unusually slow/fast typing, and
    # consistently negative sentiment—but do not label the student.
    if friction_score < 0.60:
        return {"action": "none", "reason": "no_clear_need"}

    # ---------- 4. Respect cooldowns and avoid interruption overload ----------
    if within_intervention_cooldown(
        historical_data.get("last_intervention_time"),
        cooldown_minutes=15
    ):
        return {"action": "none", "reason": "cooldown_active"}

    if too_many_recent_prompts(historical_data, limit=2, window_minutes=30):
        return {"action": "none", "reason": "prompt_frequency_limit"}

    # ---------- 5. Select the least intrusive useful intervention ----------
    # Prefer learning support before emotional framing.
    if high_error_rate(historical_data) or task_is_too_difficult(current_context):
        action = {
            "action": "offer_scaffold",
            "message": (
                "This step may be challenging. Would you like a hint, "
                "a worked example, or a simpler explanation?"
            ),
            "options": ["hint", "worked_example", "simplify", "continue"],
            "optional": True
        }

    elif likely_needs_break(historical_data, current_context):
        action = {
            "action": "offer_break",
            "message": (
                "Would you like to pause for a short break, switch activities, "
                "or continue?"
            ),
            "options": ["take_break", "switch_activity", "continue"],
            "optional": True
        }

    else:
        action = {
            "action": "neutral_check_in",
            "message": (
                "How is this activity going? You can continue, change the "
                "explanation, or pause."
            ),
            "options": ["continue", "change_explanation", "pause"],
            "optional": True
        }

    # ---------- 6. Handle explicit user disclosure separately ----------
    # Do not infer crisis from sentiment or voice metrics alone.
    if current_context and current_context.get("explicit_distress_statement"):
        action = {
            "action": "supportive_check_in",
            "message": (
                "I'm sorry this feels difficult. Would you like to pause, "
                "talk with a trusted adult or teacher, or continue with a "
                "smaller step?"
            ),
            "options": [
                "pause",
                "contact_trusted_person",
                "smaller_step",
                "continue"
            ],
            "optional": True
        }

        # For minors or high-risk educational settings, follow the institution's
        # documented safeguarding procedure; do not attempt to provide therapy.
        if current_context.get("safeguarding_concern"):
            action["follow_safeguarding_policy"] = True

    # ---------- 7. Log only the intervention outcome ----------
    # Store coarse, non-sensitive event data; never store inferred emotions
    # as facts or retain raw biometric/audio data.
    record_minimal_event(
        user_id=user_id,
        event={
            "intervention_type": action["action"],
            "accepted": None,
            "timestamp": now()
        }
    )

    return action
```

Key design constraints:

- **No covert emotional profiling:** communicate what signals are used and provide an opt-out.
- **No diagnosis:** “learning friction” or “possible difficulty” is safer than declaring that a student is anxious, depressed, or distressed.
- **No engagement manipulation:** interventions should make pausing, leaving, or seeking human help equally acceptable.
- **Human escalation only on explicit disclosures or policy-defined risks**, not on voice pitch or sentiment scores alone.
- **Measure success by learning and well-being**, such as improved comprehension or appropriate breaks—not longer sessions.

